interface.definition:
if(or(
    a!isNullOrEmpty(ri!text),
    ri!showWhen = false
  ), {},
  a!localVariables(
    local!label: ri!text & " Header",
    local!linkStyle: a!defaultValue(value: ri!linkStyle, default: "STANDALONE"),
    local!marginBelow: a!defaultValue(value: ri!marginBelow, default: "NONE"),
    {
      #"SYSTEM_SYSRULES_richTextDisplayField"(
        label: local!label,
        labelPosition: "COLLAPSED",
        accessibilityText: local!label,
        align: ri!align,
        preventWrapping: true,
        instructions: ri!instructions,
        marginAbove: ri!marginAbove,
        marginBelow: local!marginBelow,
        value: {
          displayvalue(
            ri!headingType,
            #"_a-0000e712-ad81-8000-9ba5-011c48011c48_40408",
            {
              /*FORM*/
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: ri!text,
                style: "STRONG",
                size: "LARGE_PLUS",
                color: a!defaultValue(value: ri!color, default: #"_a-0000eaa5-7858-8000-3c9d-01ef9001ef90_59831"),
                linkStyle: local!linkStyle,
                link: ri!link
              ),
              /*SECTION*/
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: ri!text,
                style: "STRONG",
                size: "LARGE",
                color: a!defaultValue(value: ri!color, default: #"_a-0000eaa5-7858-8000-3c9d-01ef9001ef90_59831"),
                linkStyle: local!linkStyle,
                link: ri!link
              ),
              /*PARAGRAPH*/
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: ri!text,
                style: "STRONG",
                size: "MEDIUM_PLUS",
                color: a!defaultValue(value: ri!color, default: #"_a-0000eaa5-7858-8000-3c9d-01ef9001ef90_59831"),
                linkStyle: local!linkStyle,
                link: ri!link
              ),
              /*LABEL*/
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: ri!text,
                style: "STRONG",
                color: a!defaultValue(value: ri!color, default: null),
                linkStyle: local!linkStyle,
                link: ri!link
              ),
              /*LEGAL*/
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: ri!text,
                style: "STRONG",
                size: "LARGE",
                color: a!defaultValue(value: ri!color, default: null),
                linkStyle: local!linkStyle,
                link: ri!link
              ),
              /* SUBHEADER */
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: ri!text,
                style: "STRONG",
                size: "MEDIUM",
                color: a!defaultValue(value: ri!color, default: #"_a-0000eaa5-7858-8000-3c9d-01ef9001ef90_59831"),
                linkStyle: local!linkStyle,
                link: ri!link
              ),
              /*LEGAL SUBHEADER*/
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: ri!text & "    ",
                size: "MEDIUM_PLUS",
                style: "EMPHASIS",
                linkStyle: local!linkStyle,
                link: ri!link
              ),
              /*LEGAL SOFT HEADER*/
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: ri!text & "    ",
                size: "MEDIUM_PLUS",
                color: "#6B6B6B",
                linkStyle: local!linkStyle,
                link: ri!link
              )
            },
            /*SECTION*/
            #"SYSTEM_SYSRULES_richTextItem_v1"(
              text: ri!text,
              style: "STRONG",
              size: "LARGE",
              color: a!defaultValue(value: ri!color, default: #"_a-0000eaa5-7858-8000-3c9d-01ef9001ef90_59831"),
              linkStyle: local!linkStyle,
              link: ri!link
            )
          ),
          if(a!isNullOrEmpty(ri!icon), {},
            {
              "  ",
              #"SYSTEM_SYSRULES_richTextIcon"(
                icon: ri!icon,
                size: 
                displayvalue(
                  ri!headingType,
                  #"_a-0000e712-ad81-8000-9ba5-011c48011c48_40408",
                  {
                    /*FORM*/
                    "LARGE_PLUS",
                    /*SECTION*/
                    "LARGE",
                    /*PARAGRAPH*/
                    "MEDIUM",
                    /*LABEL*/
                    null,
                    /*LEGAL*/
                    "LARGE",
                    /* SUBHEADER */
                    "MEDIUM",
                    /*LEGAL SUBHEADER*/
                    "LARGE",
                    /*LEGAL SOFT HEADER*/
                    "LARGE"
                  },
                  /*DEFAULT*/
                  "LARGE"
                ),
                caption: ri!helpToolTip,
                altText: ri!helpToolTip,
                color: a!defaultValue(value: ri!colorIcon, default: a!defaultValue(value: ri!color, default: #"_a-0000eaa5-7858-8000-3c9d-01ef9001ef90_59831")),
                linkStyle: "STANDALONE"
              )
            }
          )
        }
      ),
      if(ri!showHorizontalLine,
        #"SYSTEM_SYSRULES_horizontalLine"(),
        {}
      )
    }
  )
)
